// HARDCODED SECRET — replace via n8n UI; do not commit
const SECRET = 'REPLACE_WITH_32_PLUS_CHAR_HMAC_SECRET';
const BASE_URL = 'https://typing.elementops.it.com';
const TTL_DAYS = 30;

const enc = new TextEncoder();

function toBase64Url(str) {
  return btoa(str).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}

function bytesToHex(bytes) {
  return [...new Uint8Array(bytes)].map(b => b.toString(16).padStart(2, '0')).join('');
}

async function hmacSha256Hex(secret, message) {
  const key = await crypto.subtle.importKey(
    'raw', enc.encode(secret),
    { name: 'HMAC', hash: 'SHA-256' },
    false, ['sign']
  );
  const sig = await crypto.subtle.sign('HMAC', key, enc.encode(message));
  return bytesToHex(sig);
}

const body = $input.first().json.body || $input.first().json;
const recordId = body.recordId || body.record_id;

if (!recordId || typeof recordId !== 'string' || !recordId.startsWith('rec')) {
  throw new Error('missing or invalid recordId in webhook body');
}

const nowSec = Math.floor(Date.now() / 1000);
const expiresAtSec = nowSec + TTL_DAYS * 86400;
const nonceBytes = new Uint8Array(8);
crypto.getRandomValues(nonceBytes);
const nonce = bytesToHex(nonceBytes);

const payload = { r: recordId, e: expiresAtSec, n: nonce };
const tokenB64 = toBase64Url(JSON.stringify(payload));
const sig = await hmacSha256Hex(SECRET, tokenB64);
const token = tokenB64 + '.' + sig;
const url = BASE_URL + '/?t=' + token;

return [{
  json: {
    recordId: recordId,
    token: token,
    url: url,
    expiresAt: new Date(expiresAtSec * 1000).toISOString(),
    generatedAt: new Date(nowSec * 1000).toISOString()
  }
}];
